mapper.insert:
insert into book(
	book_id, book_title, book_author, 
	book_publication_date, book_price, book_publisher, 
	book_page_count, book_genre
)
values(
	#{bookId}, #{bookTitle}, #{bookAuthor}, 
	#{bookPublicationDate}, #{bookPrice}, #{bookPublisher},
	#{bookPageCount}, #{bookGenre}
)

mapper.select:
select * from (
	select rownum rn, TMP.* from (
		select * from book

			where #{lastBookId} > book_id

		order by book_id desc
	)TMP	
) where rn between 1 and #{size}
